function cloudBadge(){return `<button type="button" class="cloud-badge ${cloudPhase}" data-action="cloud" title="${esc(cloudMessage||cloudLabels[cloudPhase])}"><span class="status-dot"></span>${cloudLabels[cloudPhase]}</button>`;}
