function spendingChart(st){
 const days=new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate();
 const current=month===TODAY().slice(0,7)?Number(TODAY().slice(-2)):month<TODAY().slice(0,7)?days:0;
 const daily=Array(days).fill(0);for(const t of st.tx)if(['expense','refund'].includes(t.type))daily[Number(t.date.slice(-2))-1]+=(t.type==='refund'?-1:1)*t.amount;
 let running=0;const values=daily.map(x=>running+=x),max=Math.max(5000,...values),min=Math.min(0,...values),range=max-min;
 const x=i=>50+i/(days-1)*550,y=v=>178-(v-min)/range*133;
 const points=values.slice(0,current).map((v,i)=>`${x(i)},${y(v)}`).join(' '),has=st.tx.some(t=>['expense','refund'].includes(t.type));
 const last=current?`${x(current-1)},${y(values[current-1])}`:'50,178';
 return `<div class="spending-chart"><svg viewBox="0 0 625 210" role="img" aria-label="Wydatki narastająco w miesiącu, wyłącznie z zapisanych transakcji"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#6b8d70" stop-opacity=".18"/><stop offset="100%" stop-color="#6b8d70" stop-opacity="0"/></linearGradient></defs>${[0,.5,1].map(k=>`<line x1="50" x2="600" y1="${y(min+range*k)}" y2="${y(min+range*k)}" stroke="#e8e9e1" stroke-dasharray="3 5"/><text x="40" y="${y(min+range*k)+4}" text-anchor="end" fill="#8d958c" font-size="10">${Math.round((min+range*k)/100)}</text>`).join('')}${has&&current?`<polygon points="50,${y(0)} ${points} ${x(current-1)},${y(0)}" fill="url(#chart-fill)"/><polyline points="${points}" fill="none" stroke="#56785f" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${last.split(',')[0]}" cy="${last.split(',')[1]}" r="4.5" fill="#56785f" stroke="#fff" stroke-width="2"/>`:`<text x="325" y="105" text-anchor="middle" fill="#8d958c" font-size="13">Twój rytm pojawi się po pierwszym wydatku.</text>`}${[1,Math.round(days/2),days].map(d=>`<text x="${x(d-1)}" y="201" fill="#8d958c" font-size="10" text-anchor="middle">${d}</text>`).join('')}</svg></div>`;
}
function budgetRow(c,spent,limit){return `<div class="budget-row"><div class="row-between"><div class="budget-label"><span class="cat-icon" style="color:${c.color};background:${c.color}16">${c.icon}</span>${c.name}</div><div class="budget-numbers ${spent>limit?'over':''}"><strong>${money(spent)}</strong> / ${money(limit)}</div></div><div class="track"><span class="${spent>limit?'overbar':''}" style="width:${fraction(spent,limit)|| (spent>0?100:0)}%;background:${spent>limit?'':c.color}"></span></div></div>`;}
function txRow(t){const c=cat(t.category),positive=['income','refund','sell'].includes(t.type);return `<div class="tx-row"><span class="cat-icon" style="color:${['expense','refund'].includes(t.type)?c.color:'#698777'}">${t.type==='expense'||t.type==='refund'?c.icon:t.type==='transfer'?'⇄':positive?'↓':'↗'}</span><div class="tx-main"><div class="tx-title">${esc(t.description)}</div><div class="tx-meta">${date(t.date)} · ${esc(state.accounts.find(a=>a.id===t.account)?.name)}</div></div><div class="tx-money ${positive?'income':''}">${t.type==='transfer'?'':positive?'+':'−'}${money(t.amount)}<div class="sub">${types[t.type]}</div></div></div>`;}
function transactionsView(){return `<div class="transactions-view">${heading('Każdy zapis.<br><em>Wszystko pod ręką.</em>','Przeszukaj opisy i produkty, również w całej historii.',btn(icon('download')+' Import CSV','import','small'))}<section class="panel"><div class="filterbar transaction-filters"><input id="tx-search" type="search" placeholder="Opis lub nazwa produktu…" aria-label="Szukaj po opisie lub produkcie" value="${esc(search)}">${monthInput()}<label class="tx-all-history"><input type="checkbox" id="tx-all" ${allTransactions?'checked':''}>Cała historia</label><select id="filter-type" aria-label="Rodzaj transakcji"><option value="">Wszystkie rodzaje</option>${Object.entries(types).map(([id,label])=>`<option value="${id}" ${filterType===id?'selected':''}>${label}</option>`).join('')}</select><select id="filter-account" aria-label="Konto"><option value="">Wszystkie konta</option>${accountOptions(filterAccount)}</select><select id="filter-category" aria-label="Kategoria"><option value="">Wszystkie kategorie</option>${categories.map(c=>`<option value="${c.id}" ${filterCategory===c.id?'selected':''}>${c.name}</option>`).join('')}</select><select id="filter-subcategory" aria-label="Podkategoria" ${!filterCategory?'disabled':''}>${subcategoryOptions(filterCategory,filterSubcategory,'Wszystkie podkategorie')}<option value="none" ${filterSubcategory==='none'?'selected':''}>Bez podkategorii</option></select><select id="filter-pati" aria-label="Związek z Pati"><option value="">Wszystkie oznaczenia</option><option value="yes" ${filterPati==='yes'?'selected':''}>Związane z Pati</option><option value="no" ${filterPati==='no'?'selected':''}>Bez oznaczenia Pati</option></select><label class="transaction-day"><span>Dokładny dzień</span><input type="date" id="filter-date" value="${filterDate}" max="${TODAY()}"></label>${btn('Wyczyść filtry','clear-tx-filters','ghost small')}${btn('Eksport CSV','exportcsv','small')}</div><div id="tx-table">${transactionTable()}</div></section><p class="smallprint">Zwroty pomniejszają wydatki. Przelewy i operacje inwestycyjne są poza budżetem konsumpcyjnym. ${filterCategory?'Kwoty w wierszach to całe transakcje; podsumowanie obejmuje tylko pozycje pasujące do wybranej kategorii i podkategorii.':''}</p></div>`;}
function filteredTx(){return state.transactions.filter(t=>transactionMatches(t,{month,all:allTransactions,query:search,type:filterType,account:filterAccount,category:filterCategory,subcategory:filterSubcategory,pati:filterPati,date:filterDate})).sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id));}
function transactionTable(){const tx=filteredTx(),totals=filteredTotals(tx,filterCategory,filterSubcategory);return `<div class="tx-filter-summary"><div><span>Pasujących transakcji</span><strong>${tx.length}</strong></div><div><span>${filterSubcategory?'Wydatki podkategorii po zwrotach':filterCategory?'Wydatki kategorii po zwrotach':'Wydatki po zwrotach'}</span><strong>${money(totals.netExpenses)}</strong></div><div><span>Wpływy</span><strong>${money(totals.income)}</strong></div></div>`+(tx.length?`<div class="table-wrap"><table class="transactions-table"><thead><tr><th>Data / opis</th><th>Kategoria / rodzaj</th><th>Konto</th><th class="num">Kwota</th><th>Zmień / zapamiętaj</th></tr></thead><tbody>${tx.slice(0,txVisible).map(t=>`<tr><td class="transaction-description">${esc(t.description)}<small>${t.date}${t.items?.length?' · '+t.items.length+' pozycji':''}${t.receiptId?' · paragon':''}</small></td><td class="transaction-category"><span class="pill">${['expense','refund'].includes(t.type)?t.items?.length>1?'Podział na pozycje':cat(t.items?.[0]?.category||t.category).name:types[t.type]}</span>${['expense','refund'].includes(t.type)&&!(t.items?.length>1)?'<small>'+esc(subcategoryName(t.items?.[0]?.category||t.category,t.items?.[0]?.subcategory||(!t.items?.length?t.subcategory:'')))+'</small>':''}${t.relatedToPati?'<span class="pill pati-badge">Związane z Pati</span>':''}${t.type==='refund'?'<small>Zwrot wydatku</small>':''}</td><td class="transaction-account">${esc(state.accounts.find(a=>a.id===t.account)?.name)}${t.to?'<small>→ '+esc(state.accounts.find(a=>a.id===t.to)?.name)+'</small>':''}</td><td class="num transaction-amount ${['income','refund','sell'].includes(t.type)?'tx-money income':''}">${t.type==='transfer'?'':['income','refund','sell'].includes(t.type)?'+':'−'}${money(t.amount)}<small>${types[t.type]}</small></td><td class="transaction-actions">${btn(icon('edit'),'edit-tx','ghost small',`data-id="${esc(t.id)}" aria-label="Edytuj ${esc(t.description)}"`)}${t.type==='expense'?btn('Szablon','template-create','ghost small',`data-id="${esc(t.id)}"`):''}</td></tr>`).join('')}</tbody></table></div><div class="tx-table-footer"><span>Pokazano ${Math.min(txVisible,tx.length)} z ${tx.length}</span>${tx.length>txVisible?btn('Pokaż kolejne 50','tx-more','small'):''}</div>`:`<div class="empty">${icon('transactions')}Brak pasujących transakcji.<br>Zmień miesiąc lub filtry.${btn('Wyczyść filtry','clear-tx-filters','small')}</div>`);}
function budgetView(){
 const st=monthStats(state,month),b=budgetFor(state,month),expensePlan=Object.values(b).reduce((a,v)=>a+v,0),planned=expensePlan+state.settings.reserve+state.settings.irregular,unassigned=state.settings.income-planned;
 return heading('Każda złotówka ma swoje miejsce.','Twój miesięczny plan. Dopasuj limity do realnych potrzeb.',monthInput())+`<div class="notice green">Najpierw wpisz orientacyjny dochód i realne limity. Oddziel bieżące wydatki, większe zakupy i oszczędności. To plan, nie zapis rzeczywistych transakcji.</div><div class="split"><form id="budget-form" class="panel"><div class="panel-head"><div><h2>Limity wydatków</h2><p class="sub">Kwoty na ${esc(monthName(month))}. Nowy miesiąc dziedziczy ostatni wcześniejszy plan.</p></div></div>${categories.map(c=>`<div class="budget-editor"><div class="budget-label"><span class="cat-icon" style="color:${c.color};background:${c.color}16">${c.icon}</span><div>${c.name}${c.essential?'<div class="sub">Podstawowe / zobowiązania</div>':''}</div></div><label><input name="budget-${c.id}" type="text" inputmode="decimal" value="${number(b[c.id]||0)}" aria-label="Limit: ${c.name}"></label><div><div class="row-between sub"><span>Wydane: ${money(st.spending[c.id]||0)}</span><span class="${(st.spending[c.id]||0)>(b[c.id]||0)?'over':''}">${money((b[c.id]||0)-(st.spending[c.id]||0))} zostało</span></div><div class="track"><span class="${st.spending[c.id]>b[c.id]?'overbar':''}" style="width:${fraction(st.spending[c.id],b[c.id])}%"></span></div></div></div>`).join('')}<div class="panel-body"><div class="error" id="budget-error" role="alert"></div><div class="form-actions">${btn('Kopiuj poprzedni miesiąc','copy-budget','small')}<button class="button primary" type="submit">Zapisz plan miesiąca</button></div></div></form><div><section class="panel"><div class="panel-body"><h2>Plan podziału dochodu</h2><div class="plan-line"><span>Orientacyjny dochód netto</span><strong>${money(state.settings.income)}</strong></div><div class="plan-line"><span>Wydatki w kategoriach</span><strong>${money(expensePlan)}</strong></div><div class="plan-line"><span>Na przyszłe większe wydatki</span><strong>${money(state.settings.irregular)}</strong></div><div class="plan-line"><span>Odkładanie na poduszkę</span><strong>${money(state.settings.reserve)}</strong></div><div class="plan-line total-line"><span>${unassigned<0?'Plan przekracza dochód':'Jeszcze do zaplanowania'}</span><strong class="${unassigned<0?'over':''}">${money(Math.abs(unassigned))}</strong></div><p class="smallprint">Odkładanie to część planu, a nie wydatek. Przelew na własne konto oszczędnościowe nie pomniejsza wyniku miesiąca. Odłożoną część na większe wydatki oznacz w Celach.</p><button class="text-link" data-page="settings">Zmień dochód i odkładane kwoty ↗</button></div></section><section class="panel" style="margin-top:20px"><div class="panel-body"><h2>Jednorazowe nie znaczy nieprzewidywalne.</h2><p class="smallprint">W tym miesiącu może to być ubranie, w kolejnym naprawa albo prezent. Osobny fundusz na większe wydatki pozwala pokrywać je bez naruszania poduszki. Zacznij od jednej kategorii; rozdziel ją dopiero, gdy rzeczywiście pomoże Ci to podejmować decyzje.</p></div></section></div></div>`;
}
function goalsView(){const o=overview(state);return heading('Oszczędzaj z konkretnym celem.','Cele są częścią pieniędzy w bankach. Nie dodajemy ich drugi raz do majątku.',btn(icon('plus')+' Dodaj cel','add-goal','primary small'))+`${o.allocated>Math.max(0,o.bank-o.remaining)?'<div class="notice">Kwoty oznaczone jako odłożone na cele przekraczają środki po zabezpieczeniu budżetu. Sprawdź salda i przypisane kwoty — tych samych pieniędzy nie da się odłożyć dwa razy.</div>':''}<div class="goal-grid"><section class="panel goal-card reserve-card"><div class="row-between"><h2>${icon('shield')} Poduszka bezpieczeństwa</h2><span class="pill">Najpierw stabilność</span></div><div class="goal-value">${money(o.reserveCovered)} <span class="sub">/ ${money(o.target)}</span></div><p class="sub">${state.settings.months} miesięcy podstawowych kosztów. To propozycja do dostosowania.</p><div class="track"><span style="width:${fraction(o.reserveCovered,o.target)}%"></span></div><p class="smallprint">Liczymy z pieniędzy w bankach po odjęciu pozostałych limitów bieżącego miesiąca i środków przypisanych do innych celów. Nie obejmuje inwestycji ani gotówki XTB.</p><button class="text-link" data-page="settings">Zmień koszty podstawowe i liczbę miesięcy ↗</button></section>${state.goals.map(g=>`<section class="panel goal-card"><div class="row-between"><h2>${esc(g.name)}</h2><button class="text-link" data-action="edit-goal" data-id="${esc(g.id)}">Edytuj ↗</button></div><div class="goal-value">${money(g.saved)} <span class="sub">/ ${money(g.target)}</span></div><p class="sub">${g.due?'Do '+date(g.due)+' '+g.due.slice(0,4):'W Twoim tempie, bez presji.'}</p><div class="track"><span style="width:${fraction(g.saved,g.target)}%"></span></div><div class="row-between sub"><span>${Math.round(fraction(g.saved,g.target))}% celu</span><span>Brakuje ${money(Math.max(0,g.target-g.saved))}</span></div><p class="smallprint">„Odłożone” to oznaczenie już posiadanych pieniędzy w bankach. Przy wydatku z tego celu zmniejsz przypisaną tu kwotę.</p></section>`).join('')}</div>`;}
function investView(){return investments.view();}
function settingsView(){return heading('Ustaw raz. Wracaj, gdy coś się zmieni.','Prawdziwe salda i realny plan dają użyteczny obraz.')+features.quickLinks()+`<section class="panel" style="margin-bottom:22px"><div class="panel-body"><h2>Dostęp do konta</h2><p class="sub" style="margin:12px 0 18px">Loguj się swoim e-mailem i hasłem.</p><a class="button" href="/account/password">Ustaw lub zmień hasło</a></div></section><div class="settings-sections"><form class="panel" id="settings-form"><div class="panel-body"><h2>Twój plan finansowy</h2><div class="formgrid">${[['income','Orientacyjny dochód netto / miesiąc','Punkt odniesienia dla planu. Wpływy zapisuj osobno w Transakcjach.'],['essential','Podstawowe koszty / miesiąc','Uwzględnij wszystkie niezbędne koszty, także nieregularne uśrednione. Podaj rzeczywiste koszty podstawowe.'],['reserve','Plan odkładania na poduszkę / miesiąc','Plan nie tworzy automatycznie przelewu ani nowych pieniędzy.'],['irregular','Plan odkładania na większe wydatki / miesiąc','Po odłożeniu pieniędzy przypisz je do celu.'],['debt','Pozostałe zadłużenie łącznie','Stan długu do ręcznej aktualizacji; odejmujemy go od majątku netto.'],['expensiveDebt','W tym dług do priorytetowej spłaty','Część powyższego długu, np. drogi kredyt. Blokuje limit inwestowania.']].map(([id,label,help])=>`<label class="field"><span>${label} (zł)</span><input name="${id}" inputmode="decimal" value="${number(state.settings[id])}" required><small>${help}</small></label>`).join('')}<label class="field"><span>Poduszka: liczba miesięcy kosztów</span><input name="months" type="number" min="1" max="24" step="1" value="${state.settings.months}" required><small>Na start 6; dostosuj do swojej sytuacji. Podstawa poduszki to większa z kwot: koszt podstawowy tutaj lub suma podstawowych kategorii w bieżącym budżecie.</small></label></div><label class="checkline"><input name="verified" type="checkbox" ${state.settings.verified?'checked':''}><span>Sprawdziłem salda, koszty podstawowe, długi i cele. Rozumiem, że plan dochodu i budżet są wartościami orientacyjnymi.</span></label><div class="error" id="settings-error" role="alert"></div><div class="form-actions"><button class="button primary" type="submit">Zapisz ustawienia</button></div></div></form><section class="panel"><div class="panel-body"><h2>Konta i salda początkowe</h2><p class="sub">Wpisz saldo na początek wybranego dnia, przed transakcjami z tego dnia. Potem dodawaj tylko transakcje od tej daty. Nie wpisuj dzisiejszego salda i ponownie całej historii — to policzyłoby te same pieniądze dwa razy.</p>${state.accounts.map(a=>`<div class="balance-edit"><div class="field"><span>${esc(a.name)}</span><small>Aktualnie: ${money(balances(state)[a.id])}</small></div><div class="field"><span>Saldo początkowe</span><strong>${money(a.opening)}</strong></div><div class="field"><span>Od ${date(a.start)} ${a.start.slice(0,4)}</span><button class="button small" data-action="edit-account" data-id="${esc(a.id)}">Edytuj konto</button></div></div>`).join('')}<div class="form-actions">${btn('Dodaj konto / gotówkę','add-account','small')}</div></div></section><section class="panel"><div class="panel-body"><h2>Twoje dane i kopie zapasowe</h2><p class="sub">Po włączeniu synchronizacji dane są zapisywane w prywatnej bazie i dostępne po zalogowaniu na Twoje konto na innych urządzeniach. Przeglądarka zachowuje również lokalną kopię. Sprawdzaj status zapisu u góry ekranu. Kopia JSON pozwala zachować dodatkową wersję; CSV służy do analizy.</p><div class="backup-buttons">${btn(icon('download')+' Pobierz pełną kopię JSON','backup','primary')}${btn('Odtwórz z JSON','restore')}${btn('Eksport transakcji CSV','export-all')}${storageError?btn('Pobierz surowe zapisane dane','raw-backup'):''}</div><p class="smallprint">Ostatnia pobrana kopia: ${state.backupAt?new Date(state.backupAt).toLocaleString('pl-PL'):'jeszcze nie pobrano'}. Kopia zawiera dane finansowe w zwykłym tekście; przechowuj ją w swoim zaufanym miejscu. Odtworzenie zastępuje stan aplikacji. Zapisz kopię przed zmianą urządzenia i co najmniej raz w tygodniu.</p><div class="notice" style="margin-top:18px;margin-bottom:0">Połączenia bankowe aktywujesz osobno w zakładce Połączenia. Sam hosting i zapis w chmurze nie dają dostępu do banków. Liczbę jednostek XTB wpisujesz ręcznie; ceny wybranych akcji i ETF-ów aktualizują się automatycznie.</div></div></section></div>`;}
function guideView(){return heading('Prosty rytm, który da się utrzymać.','System ma pomagać Ci żyć, a nie zabierać cały wieczór.')+`<div class="split"><section class="panel"><div class="panel-body"><h2>Twój rytm</h2>${[['Codziennie · około 30 sekund','Dodaj kwotę, krótki opis i kategorię. Użyj „Dodaj transakcję” albo klawisza N. Najczęstsze kategorie wybierzesz jednym kliknięciem.'],['Raz w tygodniu · około 5 minut','Sprawdź wydatki jednorazowe, porównaj salda z bankami, popraw brakujące zapisy i pobierz kopię JSON. Nie traktuj wpisanego dochodu jako otrzymanych pieniędzy.'],['Raz w miesiącu · około 15 minut','Dostosuj limity, sprawdź podstawowe koszty i długi. Wykonaj rzeczywiste przelewy oszczędnościowe w swoim banku. Środki na większe wydatki przypisz do celu.'],['Dopiero później · decyzja o inwestowaniu','Zweryfikuj wydatki po pełnym miesiącu obserwacji. Gdy budżet, cele i poduszka są zabezpieczone, oceń horyzont i ryzyko. Nie musisz inwestować co miesiąc.']].map(([title,body],i)=>`<div class="rule"><span class="rule-num">${i+1}</span><div><h3>${title}</h3><p>${body}</p></div></div>`).join('')}</div></section><section class="panel"><div class="panel-body"><h2>Jak liczymy pieniądze</h2>${[
 ['Wpływ, wydatek czy przelew?','Pensja i inne nowe pieniądze to wpływ. Zakup to wydatek. Przelew BNP → Millennium albo bank → XTB to jedna operacja „Przelew własny” z dwoma kontami. Nie jest ani nowym dochodem, ani kosztem. W imporcie zapisz tylko jedną stronę przelewu.'],
 ['Co oznacza pozostały budżet?','Suma niewykorzystanych limitów kategorii w wybranym miesiącu. Przekroczenie jednej kategorii nie pomniejsza automatycznie pozostałych — zmień plan świadomie. To nie jest kwota na Twoim koncie.'],
 ['Poduszka i cele bez podwójnego liczenia','Pieniądze na cel nadal są częścią salda bankowego. Po odjęciu pozostałego budżetu i wszystkich celów reszta może pokrywać poduszkę. Dopiero nadwyżka ponad jej pełny cel jest pokazywana jako potencjalna kwota na inwestycje.'],
 ['Dlaczego plan nie zmienia sald?','Plan dochodu, odkładania i wydatków to zamiary. Salda zmieniają tylko zapisane transakcje i salda początkowe. Uzgadniaj je z rzeczywistymi kontami.'],
 ['Jak zacząć od aktualnych sald?','Najłatwiej wybierz dzisiaj jako datę początku dla wszystkich kont. Wpisz salda sprzed pierwszej dzisiejszej transakcji, którą zapiszesz. Nie importuj wcześniejszej historii. Chcąc pełny miesiąc, wpisz salda z początku miesiąca i dodaj historię od tego dnia.'],
 ['Jak używać CSV?','Pobierz historię banku jako CSV, jeżeli bank udostępnia ten format. Wybierz konto, kodowanie i kolumny. Sprawdź daty, znaki kwot i rodzaje transakcji. Przelewy własne oznacz ręcznie z kontem docelowym. Podobne wiersze są odznaczane jako możliwe duplikaty — prawdziwe identyczne zakupy możesz przywrócić.'],
 ['Co z inwestycjami i walutami?','Wszystkie kwoty aplikacji są w PLN. Pozycje XTB są ręcznie aktualizowaną migawką, wycenioną przez Ciebie w PLN. Koszt to koszt pozostających otwartych pozycji. Zakup/sprzedaż zmienia gotówkę XTB, a migawkę aktualizujesz osobno. Nie ma automatycznych notowań, rozliczenia podatku ani pomiaru całkowitej stopy zwrotu.']
 ].map(([title,body])=>`<details class="guide-details"><summary>${title}</summary><p>${body}</p></details>`).join('')}</div></section></div>`;}
function connectionsView(){return heading('Twoje banki,<br><em>bliżej Twojego planu.</em>','Sprawdzona ścieżka połączenia. Dostęp wyłącznie do odczytu.')+`<div class="connection-grid">${[['BNP','BNP Paribas Polska',''],['M','Bank Millennium','mill']].map(([mark,name,cls])=>`<section class="panel connection-card"><span class="bank-logo ${cls}">${mark}</span><span class="pill">Dostępny przez Enable Banking</span><h2>${name}</h2><p>Odczyt rachunków, sald i historii po autoryzacji w banku.</p><div class="connection-state"><span class="status-dot"></span>Jeszcze niepołączony</div>${btn('Zobacz sposób aktywacji '+icon('arrow'),'bank-setup','small')}</section>`).join('')}</div><section class="panel" style="margin-top:22px"><div class="panel-body"><h2>Co zostało sprawdzone?</h2><div class="rule"><span class="rule-num">1</span><div><h3>Oba banki są w katalogu produkcyjnym.</h3><p>Enable Banking wymienia BNP Paribas Polska i Millennium dla usługi informacji o rachunku (AIS).</p></div></div><div class="rule"><span class="rule-num">2</span><div><h3>Jest ścieżka do użytku osobistego.</h3><p>Aktualny regulamin dopuszcza bezpłatny dostęp produkcyjny do własnych powiązanych rachunków. Obowiązują warunki dostawcy i ewentualne limity.</p></div></div><div class="rule"><span class="rule-num">3</span><div><h3>Potrzebna jest Twoja aktywacja.</h3><p>Rejestracja aplikacji Production, klucz serwerowy i powiązanie własnych rachunków nie są jeszcze wykonane. Ta wersja aplikacji nie pobiera danych bankowych; działają ręczne zapisy i CSV.</p></div></div><p class="smallprint">Źródła: <a href="https://enablebanking.com/open-banking-apis?country=PL" target="_blank" rel="noopener noreferrer">Katalog banków</a> · <a href="https://enablebanking.com/terms/" target="_blank" rel="noopener noreferrer">Warunki dostępu</a> · <a href="https://enablebanking.com/docs/api/control-panel/" target="_blank" rel="noopener noreferrer">Panel aplikacji</a></p></div></section><div class="notice green" style="margin-top:20px">Bezpośrednie produkcyjne API banków jest przeznaczone dla uprawnionych dostawców TPP. Dlatego dla prywatnego organizera wybieramy pośrednika. Połączenie ma obejmować odczyt danych, bez inicjowania przelewów.</div>`;}
function showBankSetup(){openModal('Jak uruchomimy połączenie?',`<p class="sub">Przygotowana aplikacja ma prywatny hosting i bazę. Do aktywacji banków potrzebne będzie Twoje konto Enable Banking i osobista zgoda w bankach.</p><div class="rule"><span class="rule-num">1</span><div><h3>Utwórz aplikację Production w Enable Banking.</h3><p>Tryb testowy korzysta z danych przykładowych. Dostawca wymaga także informacji o prywatności i warunkach aplikacji.</p></div></div><div class="rule"><span class="rule-num">2</span><div><h3>Powiąż własne rachunki w panelu dostawcy.</h3><p>To umożliwia ograniczony dostęp do Twoich kont. Autoryzacja odbywa się na stronach banków.</p></div></div><div class="rule"><span class="rule-num">3</span><div><h3>Dokończymy konektor po aktywacji.</h3><p>Klucz prywatny trafi wyłącznie do sekretów serwera. Następnie dodamy autoryzację aplikacji, odczyt transakcji i zatwierdzanie importu. Samo powiązanie kont w panelu nie wystarcza.</p></div></div><div class="notice">Nie wklejaj tutaj hasła do banku, kodów SMS ani klucza prywatnego. Obecnie żaden bank nie jest połączony.</div><div class="form-actions"><a class="button primary" href="https://enablebanking.com/docs/api/control-panel/" target="_blank" rel="noopener noreferrer">Otwórz instrukcję Enable Banking ↗</a></div>`);}
function showCloud(){
 if(demo){toast('Tryb przykładowy nie zapisuje danych w chmurze.');return;}
 if(cloudPhase==='loading'){toast('Sprawdzamy dane w chmurze.');return;}
 if(cloudPhase==='migration'){openModal('Przenieś zapisy do prywatnej chmury',`<p class="sub">${realState.transactions.length} transakcji · ${realState.accounts.length} kont · ${realState.goals.length} celów</p><p class="notice green" style="margin-top:18px">Zapiszemy obecny stan w bazie powiązanej z Twoim kontem. Lokalna kopia pozostanie na urządzeniu. Potem dane będą dostępne po zalogowaniu również na innym urządzeniu.</p><div class="form-actions">${btn('Pobierz kopię JSON','backup')}<button class="button primary" id="migrate-confirm">Przenieś i włącz synchronizację</button></div>`);modal.querySelector('#migrate-confirm').onclick=()=>{cloud.migrate(realState);modal.close();};return;}
 if(cloudPhase==='conflict'){openModal('Zachowaj właściwą wersję',`<p class="sub">W chmurze lub drugiej karcie pojawiły się inne zapisy. Nie scalimy ich automatycznie, aby nie dublować transakcji. Najpierw pobierz kopię lokalnych danych.</p><div class="notice" style="margin-top:18px">Wybranie wersji z chmury zastąpi stan na tym urządzeniu. Wybranie lokalnej wersji zastąpi stan w chmurze. Obie operacje wymagają świadomego wyboru.</div><div class="form-actions">${btn('Pobierz lokalną kopię','backup')}<button id="use-cloud" class="button">Użyj wersji z chmury</button><button id="keep-local" class="button primary">Zachowaj lokalną wersję</button></div>`);modal.querySelector('#use-cloud').onclick=async()=>{try{await cloud.useCloud();modal.close();render();toast('Wczytano wersję z chmury');}catch(e){toast(e.message);}};modal.querySelector('#keep-local').onclick=async()=>{try{await cloud.keepLocal(realState);modal.close();}catch(e){toast(e.message);}};return;}
 if(cloudPhase==='offline'){if(storageError)toast('Najpierw pobierz surową kopię i odtwórz dane w Ustawieniach.');else cloud.retry(realState);return;}
 toast(cloudPhase==='saving'?'Trwa zapisywanie ostatnich zmian.':'Twoje dane są zapisane w prywatnej chmurze.');
}
function bindView(){
 document.querySelectorAll('[data-month]').forEach(el=>el.addEventListener('change',()=>{if(/^\d{4}-\d{2}$/.test(el.value)){month=el.value;render();}}));
 const update=()=>{txVisible=50;document.querySelector('#tx-table').innerHTML=transactionTable();};
 document.querySelector('#tx-search')?.addEventListener('input',e=>{search=e.target.value;update();});
 document.querySelector('#filter-type')?.addEventListener('change',e=>{filterType=e.target.value;update();});
 document.querySelector('#filter-account')?.addEventListener('change',e=>{filterAccount=e.target.value;update();});
 document.querySelector('#filter-subcategory')?.addEventListener('change',e=>{filterSubcategory=e.target.value;update();});
 document.querySelector('#filter-pati')?.addEventListener('change',e=>{filterPati=e.target.value;update();});
 document.querySelector('#filter-category')?.addEventListener('change',e=>{filterCategory=e.target.value;filterSubcategory='';render();});
 document.querySelector('#filter-date')?.addEventListener('change',e=>{filterDate=e.target.value;if(filterDate)allTransactions=true;render();});
 document.querySelector('#tx-all')?.addEventListener('change',e=>{allTransactions=e.target.checked;update();document.querySelector('.transaction-filters [data-month]').disabled=allTransactions;});
 if(page==='transactions')document.querySelector('.transaction-filters [data-month]').disabled=allTransactions;
 document.querySelector('#budget-form')?.addEventListener('submit',e=>{
  e.preventDefault();const fd=new FormData(e.target),b={};
  for(const c of categories){const n=moneyInput(fd.get('budget-'+c.id));if(!Number.isFinite(n)||n<0){document.querySelector('#budget-error').textContent='Podaj poprawne, nieujemne limity w złotych.';return;}b[c.id]=n;}
  commit(s=>{s.budgets[month]=b;},'Zapisano budżet na '+monthName(month));
 });
 document.querySelector('#settings-form')?.addEventListener('submit',e=>{
  e.preventDefault();const fd=new FormData(e.target),settings={...state.settings};
  for(const key of ['income','essential','reserve','irregular','debt','expensiveDebt']){settings[key]=moneyInput(fd.get(key));if(!Number.isFinite(settings[key])||settings[key]<0){document.querySelector('#settings-error').textContent='Podaj poprawne, nieujemne kwoty.';return;}}
  settings.months=Number(fd.get('months'));settings.verified=fd.get('verified')==='on';
  if(settings.expensiveDebt>settings.debt){document.querySelector('#settings-error').textContent='Dług do priorytetowej spłaty nie może przekraczać łącznego zadłużenia.';return;}
  commit(s=>{s.settings=settings;},'Zapisano Twój plan');
 });
}
function openModal(title,body,wide=false){modal.className=wide?'wide':'';modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="button ghost small" data-action="close" aria-label="Zamknij">${icon('close')}</button></div><div class="modal-body">${body}</div>`;modal.showModal();}
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
function showTransaction(id=null,kind='expense',prefill=null,resumed=null){
 if(!resumed&&drafts().read()){pendingTransaction={id,kind,prefill};offerDraft();return;}
 const old=state.transactions.find(t=>t.id===id),t=resumed?draftPrefill(resumed):old||prefill||{amount:0,date:TODAY(),description:'',category:'once',account:['buy','sell'].includes(kind)?'xtb':sessionStorage.getItem('spokojnie-last-account')||'bnp',type:kind,to:'mill'};
 openModal(old?'Edytuj transakcję':'Zapisz i wróć do swojego dnia.',`<form id="tx-form"><div class="segmented">${['expense','income','transfer','refund','buy','sell'].map(type=>`<button type="button" data-txtype="${type}" class="${t.type===type?'active':''}">${types[type]}</button>`).join('')}</div><input name="type" type="hidden" value="${t.type}"><label class="field"><span>Kwota (zł)</span><input class="amount-input" name="amount" inputmode="decimal" placeholder="0,00" value="${t.amount?number(t.amount):''}" required autocomplete="off"></label><label class="field"><span>Krótki opis</span><input name="description" value="${esc(t.description)}" placeholder="np. zakupy, autobus, wynagrodzenie" maxlength="160" required></label><div id="category-area"><label class="field"><span>Kategoria</span><select name="category">${categories.map(c=>`<option value="${c.id}" ${c.id===t.category?'selected':''}>${c.name}</option>`).join('')}</select></label><label class="field subcategory-field"><span>Podkategoria</span><select name="subcategory">${subcategoryOptions(t.category,t.subcategory)}</select><small>Najpierw wybierz kategorię. Starsze wpisy mogą pozostać bez podkategorii.</small></label><div class="quick-cats">${categories.slice(0,6).map(c=>`<button type="button" data-quickcat="${c.id}" class="${c.id===t.category?'selected':''}">${c.icon} ${c.name}</button>`).join('')}</div><label class="checkline pati-check"><input type="checkbox" name="relatedToPati" ${t.relatedToPati===true?'checked':''}><span>Związane z Pati<small>Wspólny posiłek, prezent lub inny wydatek związany z Pati. Oznaczenie dotyczy całej kwoty.</small></span></label></div><div class="formgrid"><label class="field"><span id="account-label">Konto</span><select name="account">${accountOptions(t.account)}</select></label><label class="field"><span>Data</span><input name="date" type="date" value="${t.date}" max="${TODAY()}" required></label><label class="field full" id="to-area"><span>Konto docelowe</span><select name="to">${accountOptions(t.to||'mill')}</select><small>Jeden przelew aktualizuje oba konta. Nie dodawaj osobno drugiej strony.</small></label></div><p id="trade-note" class="notice">Kwota całkowita w PLN, po uwzględnieniu opłat. Ta operacja zmienia tylko gotówkę XTB. Zaktualizuj również wartość i koszt otwartych pozycji w Inwestycjach.</p><div class="error" id="tx-error" role="alert"></div><div class="form-actions">${old?btn('Usuń','delete-tx','danger',`data-id="${esc(old.id)}"`):''}<button class="button primary" type="submit">${old?'Zapisz zmiany':'Zapisz transakcję'}</button></div></form>`);
 const form=modal.querySelector('#tx-form');features.enhanceTransaction(form,t);
 bindSubcategory(form.elements.category,form.elements.subcategory);
 form.elements.category.addEventListener('change',()=>modal.querySelectorAll('[data-quickcat]').forEach(b=>b.classList.toggle('selected',b.dataset.quickcat===form.elements.category.value)));
 const draftNotice=document.createElement('p');draftNotice.className='draft-form-note';draftNotice.textContent='Niedokończony wpis zapamiętamy na tym urządzeniu przez 7 dni.';form.querySelector('.form-actions').before(draftNotice);
 const persistDraft=()=>{if(!form.isConnected)return;const ok=drafts().save(captureTransactionDraft(form,old?.id||null,t.receiptId));draftNotice.textContent=ok?'Wersja robocza zapisana na tym urządzeniu. Nie zmienia jeszcze budżetu.':'Brak miejsca na wersję roboczą. Zapisz transakcję przed zamknięciem formularza.';};form.addEventListener('input',persistDraft);form.addEventListener('change',persistDraft);form.addEventListener('click',e=>{if(e.target.closest('button:not([type=submit])'))queueMicrotask(persistDraft);});
 if(resumed)restoreDraftFields(form,resumed);
 const updateType=()=>{const type=form.elements.type.value;form.dispatchEvent(new Event('product-type-change'));modal.querySelector('#category-area').hidden=!['expense','refund'].includes(type);for(const field of modal.querySelectorAll('#category-area input,#category-area select'))field.disabled=!['expense','refund'].includes(type);modal.querySelector('#to-area').hidden=type!=='transfer';modal.querySelector('#trade-note').hidden=!['buy','sell'].includes(type);modal.querySelector('#account-label').textContent=type==='transfer'?'Z konta':'Konto';modal.querySelectorAll('[data-txtype]').forEach(b=>b.classList.toggle('active',b.dataset.txtype===type));if(['buy','sell'].includes(type)&&state.accounts.find(a=>a.id===form.elements.account.value)?.kind!=='broker')form.elements.account.value=state.accounts.find(a=>a.kind==='broker')?.id||'';};updateType();
 modal.querySelectorAll('[data-txtype]').forEach(b=>b.addEventListener('click',()=>{form.elements.type.value=b.dataset.txtype;updateType();}));
 modal.querySelectorAll('[data-quickcat]').forEach(b=>b.addEventListener('click',()=>{form.elements.category.value=b.dataset.quickcat;form.elements.category.dispatchEvent(new Event('change'));form.dispatchEvent(new Event('change'));modal.querySelectorAll('[data-quickcat]').forEach(c=>c.classList.toggle('selected',c===b));}));
 form.addEventListener('submit',e=>{
  e.preventDefault();const fd=new FormData(form),next={...old,id:old?.id||uid(),type:fd.get('type'),amount:moneyInput(fd.get('amount')),description:String(fd.get('description')).trim(),date:fd.get('date'),account:fd.get('account'),category:fd.get('category')};delete next.subcategory;delete next.relatedToPati;if(['expense','refund'].includes(next.type)){if(fd.get('subcategory'))next.subcategory=fd.get('subcategory');next.relatedToPati=fd.get('relatedToPati')==='on';}if(next.type==='transfer')next.to=fd.get('to');else delete next.to;next.items=features.readItems(form);if(prefill?.receiptId)next.receiptId=prefill.receiptId;if(next.type!=='expense'){delete next.recurringId;delete next.scheduledDate;}
  try{validateTransaction(next,state);}catch(err){modal.querySelector('#tx-error').textContent=err.message;return;}
  if(commit(s=>{if(old)s.transactions[s.transactions.findIndex(x=>x.id===old.id)]=next;else s.transactions.push(next);syncLinkedPurchase(s,next);},old?'Zaktualizowano transakcję':'Transakcja zapisana')){try{sessionStorage.setItem('spokojnie-last-account',next.account);}catch{}drafts().clear();modal.close();render();}
 });
 setTimeout(()=>form.elements.amount.focus(),60);
}
function showGoal(id){const old=state.goals.find(g=>g.id===id);openModal(old?'Zmień cel':'Na co odkładasz?',`<form id="goal-form"><label class="field"><span>Nazwa celu</span><input name="name" value="${esc(old?.name||'')}" maxlength="100" placeholder="np. laptop, wakacje, większe wydatki" required></label><div class="formgrid"><label class="field"><span>Potrzebna kwota (zł)</span><input name="target" inputmode="decimal" value="${old?number(old.target):''}" required></label><label class="field"><span>Już odłożone (zł)</span><input name="saved" inputmode="decimal" value="${number(old?.saved||0)}" required></label></div><label class="field"><span>Termin (opcjonalnie)</span><input name="due" type="date" value="${old?.due||''}"></label><p class="notice green">Wpisz wyłącznie pieniądze, które już posiadasz w bankach i przeznaczasz na ten cel. Nie dopisujemy ich drugi raz do majątku ani nie wykonujemy przelewu. Te same środki nie powinny pokrywać innych celów.</p><div class="error" id="goal-error" role="alert"></div><div class="form-actions">${old?btn('Usuń cel','delete-goal','danger',`data-id="${esc(old.id)}"`):''}<button class="button primary" type="submit">Zapisz cel</button></div></form>`);modal.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target),g={id:old?.id||uid(),name:String(fd.get('name')).trim(),target:moneyInput(fd.get('target')),saved:moneyInput(fd.get('saved')),due:fd.get('due')};if(!g.name||!Number.isFinite(g.target)||g.target<=0||!Number.isFinite(g.saved)||g.saved<0){modal.querySelector('#goal-error').textContent='Podaj nazwę, dodatnią kwotę celu i nieujemną odłożoną kwotę.';return;}if(commit(s=>{if(old)s.goals[s.goals.findIndex(x=>x.id===old.id)]=g;else s.goals.push(g);},'Zapisano cel'))modal.close();});}
function showHolding(id){return investments.edit(id);}
function showAccount(id){const old=state.accounts.find(a=>a.id===id);openModal(old?'Ustaw konto i punkt startowy':'Dodaj konto',`<form id="account-form"><label class="field"><span>Nazwa konta</span><input name="name" value="${esc(old?.name||'')}" maxlength="80" required></label><label class="field"><span>Rodzaj</span><select name="kind"><option value="bank" ${old?.kind!=='broker'?'selected':''}>Bank / oszczędności / gotówka</option><option value="broker" ${old?.kind==='broker'?'selected':''}>Wolna gotówka u brokera</option></select></label><label class="field"><span>Saldo początkowe (zł)</span><input name="opening" inputmode="decimal" value="${number(old?.opening||0)}" required><small>Może być ujemne. To punkt startowy, a nie dzisiejsze saldo powiększane o całą historię.</small></label><label class="field"><span>Saldo na początek dnia</span><input name="start" type="date" value="${old?.start||TODAY()}" max="${TODAY()}" required></label><p class="notice">Zapisane transakcje będą doliczane do tego salda. Data początku nie może być późniejsza od istniejących transakcji tego konta. Porównaj wynik z bankiem po zmianie.</p><div class="error" id="account-error" role="alert"></div><div class="form-actions"><button class="button primary" type="submit">Zapisz konto</button></div></form>`);modal.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target),a={id:old?.id||uid(),name:String(fd.get('name')).trim(),kind:fd.get('kind'),opening:moneyInput(fd.get('opening')),start:fd.get('start')};if(!a.name||!Number.isFinite(a.opening)||!dateInput(a.start)||a.start>TODAY()){modal.querySelector('#account-error').textContent='Sprawdź nazwę, kwotę i datę salda.';return;}if(state.transactions.some(t=>(t.account===a.id||t.to===a.id)&&t.date<a.start)){modal.querySelector('#account-error').textContent='Istnieją wcześniejsze transakcje tego konta. Wybierz wcześniejszą datę salda początkowego.';return;}if(old?.kind==='broker'&&a.kind!=='broker'&&state.transactions.some(t=>t.account===a.id&&['buy','sell'].includes(t.type))){modal.querySelector('#account-error').textContent='To konto zawiera operacje inwestycyjne; zachowaj rodzaj brokera.';return;}if(commit(s=>{if(old)s.accounts[s.accounts.findIndex(x=>x.id===old.id)]=a;else s.accounts.push(a);s.settings.verified=false;},'Zapisano konto. Sprawdź i potwierdź ustawienia.'))modal.close();});}
function confirmDelete(kind,id){const collection={tx:'transactions',goal:'goals',holding:'holdings'}[kind];openModal('Usunąć ten zapis?',`<p class="sub">${kind==='tx'?'Usunięcie transakcji przeliczy salda i budżet. Jeżeli to zakup powiązany z pozycją, pozycja pozostanie, a jej gotówka będzie oznaczona do sprawdzenia.':kind==='goal'?'Pieniądze przestaną być zarezerwowane na ten cel. Salda banków nie zmienią się.':'Usunięcie pozycji zmieni wartość portfela. Nie zapisze sprzedaży ani nie zmieni gotówki XTB.'}</p><div class="form-actions">${btn('Zostaw','close')}${btn('Usuń zapis','confirm-delete','danger',`data-kind="${kind}" data-id="${esc(id)}"`)}</div>`);}
function download(content,name,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function backup(){const copy=structuredClone(state);copy.backupAt=new Date().toISOString();download(JSON.stringify({format:'spokojnie-finanse',exportedAt:copy.backupAt,demo,state:copy},null,2),`spokojnie-${demo?'PRZYKLAD-':''}${TODAY()}.json`,'application/json');if(!storageError)commit(s=>{s.backupAt=copy.backupAt;},'Pobrano kopię JSON');}
function exportCSV(all=false){const tx=all?state.transactions:filteredTx();const cell=v=>{let str=String(v??'');if(/^[=+@-]/.test(str)&&!/^[-+]?\d+(\.\d+)?$/.test(str))str="'"+str;return '"'+str.replace(/"/g,'""')+'"';};const rows=[['Data','Rodzaj','Opis','Kwota PLN','Kategoria','Podkategoria','Związane z Pati','Kategorie pozycji','Konto','Konto docelowe'],...tx.map(t=>[t.date,types[t.type],t.description,number(t.amount),['expense','refund'].includes(t.type)?cat(t.category).name:'',['expense','refund'].includes(t.type)?subcategoryName(t.category,t.subcategory):'',t.relatedToPati?'Tak':'',(t.items||[]).map(i=>i.name+': '+cat(i.category).name+' / '+subcategoryName(i.category,i.subcategory)).join(' | '),state.accounts.find(a=>a.id===t.account)?.name,t.to?state.accounts.find(a=>a.id===t.to)?.name:''])];download('\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),`spokojnie-transakcje-${all?'wszystkie':month}.csv`,'text/csv;charset=utf-8');toast('Pobrano '+tx.length+' transakcji. Do odtworzenia użyj kopii JSON.');}
document.querySelector('#restore-file').addEventListener('change',async e=>{
 const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>20000000){toast('Kopia jest zbyt duża (maks. 20 MB).');return;}
 try{const data=JSON.parse(await f.text()),next=data.state||data;validateState(next);openModal('Odtworzyć tę kopię?',`<p class="sub">${esc(f.name)}${data.demo?'<br><strong class="over">To kopia danych przykładowych.</strong>':''}<br>${next.transactions.length} transakcji · ${next.accounts.length} kont · ${next.goals.length} celów</p><p class="notice" style="margin-top:18px">Zastąpisz ${demo?'dane przykładowe':'obecne dane w tej przeglądarce'}. Pobierz najpierw kopię obecnego stanu, jeżeli chcesz go zachować.</p><div class="form-actions">${btn('Pobierz obecną kopię','backup')}${btn('Anuluj','close')}<button id="restore-confirm" class="button primary">Odtwórz dane</button></div>`);modal.querySelector('#restore-confirm').addEventListener('click',()=>{try{if(demo)state=demoState=structuredClone(next);else{localStorage.setItem(KEY,JSON.stringify(next));state=realState=structuredClone(next);storageError='';if(cloud.enabled)cloud.save(realState);else cloud.bootstrap(realState);}modal.close();render();toast('Dane odtworzone');}catch{toast('Nie udało się zapisać kopii. Obecne dane zachowano.');}});}catch(err){toast(err.message.includes('kopia')?err.message:'Nieprawidłowy plik JSON. Dane nie zostały zmienione.');}
});
function makeDemo(){const s=initialState(),start=TODAY().slice(0,7)+'-01',d=TODAY();s.accounts[0].opening=9000;s.accounts[1].opening=95000;s.accounts[2].opening=40000;s.accounts[3].opening=30000;s.accounts[4].opening=0;s.settings.verified=true;s.settings.income=300000;s.settings.essential=50000;s.budgets[TODAY().slice(0,7)]={fixed:50000,once:100000};s.goals[0].saved=25000;const tx=[['income',300000,'Dochód miesięczny','other','bnp'],['expense',12900,'Abonamenty i telefon','fixed','bnp'],['expense',8400,'Zakupy do domu','once','bnp'],['expense',4900,'Prezent urodzinowy','once','mill'],['expense',1950,'Drobne zakupy','once','bnp'],['transfer',20000,'Odkładam na przyszłość','other','bnp']];s.transactions=tx.map(([type,amount,description,category,account],i)=>({id:'demo-'+i,type,amount,description,category,account,date:d.slice(0,8)+String(Math.min(Number(d.slice(-2)),[1,2,4,7,10,13][i])).padStart(2,'0'),...(type==='transfer'?{to:'bnp-save'}:{})}));return s;}
app.addEventListener('click',handleClick);modal.addEventListener('click',handleClick);
function handleClick(e){
 const nav=e.target.closest('[data-page]');if(nav){features.sound();navigate(nav.dataset.page);return;}
 const el=e.target.closest('[data-action]');if(!el)return;const id=el.dataset.id;if(workspace.action(el.dataset.action,el))return;
 switch(el.dataset.action){
 case 'add':showTransaction();break;case 'trade':showTransaction(null,'buy');break;case 'edit-tx':showTransaction(id);break;
 case 'cloud':showCloud();break;case 'cloud-retry':if(storageError)toast('Najpierw odtwórz dane w Ustawieniach.');else cloud.retry(realState);break;case 'bank-setup':showBankSetup();break;
 case 'setup':navigate('settings');break;case 'close':modal.close();break;
 case 'add-goal':showGoal();break;case 'edit-goal':showGoal(id);break;
 case 'add-holding':showHolding();break;case 'edit-holding':showHolding(id);break;
 case 'add-account':showAccount();break;case 'edit-account':showAccount(id);break;
 case 'delete-tx':confirmDelete('tx',id);break;case 'delete-goal':confirmDelete('goal',id);break;case 'delete-holding':confirmDelete('holding',id);break;
 case 'confirm-delete':{const key={tx:'transactions',goal:'goals',holding:'holdings'}[el.dataset.kind],entry=structuredClone(state[key].find(x=>x.id===id));let linkedHoldings=[];if(commit(s=>{s[key]=s[key].filter(x=>x.id!==id);if(key==='transactions')linkedHoldings=detachPurchase(s,id);},'Usunięto zapis')){lastUndo={key,entry,linkedHoldings,demo,until:Date.now()+60000};if(drafts().read()?.sourceId===id)drafts().clear();modal.close();render();setTimeout(()=>{if(lastUndo?.until<=Date.now()){lastUndo=null;render();}},60050);}break;}
 case 'undo-delete':{const undo=lastUndo;if(!undo||undo.demo!==demo||undo.until<Date.now())break;if(commit(s=>{if(s[undo.key].some(x=>x.id===undo.entry.id))throw Error('Ten wpis już istnieje.');const entry=structuredClone(undo.entry);if(entry.receiptId&&!s.receipts?.some(r=>r.id===entry.receiptId))delete entry.receiptId;if(undo.key==='holdings'&&entry.purchaseTransactionId&&(!s.transactions.some(t=>t.id===entry.purchaseTransactionId&&t.type==='buy'&&t.amount===entry.cost&&(entry.mode!=='auto'||t.date===entry.purchaseDate))||s.holdings.some(h=>h.purchaseTransactionId===entry.purchaseTransactionId)))delete entry.purchaseTransactionId;s[undo.key].push(entry);if(undo.key==='transactions')restorePurchaseLinks(s,entry,undo.linkedHoldings);},'Przywrócono zapis')){lastUndo=null;render();}break;}
 case 'draft-resume':resumeDraft();break;case 'draft-discard':drafts().clear();pendingTransaction=null;modal.close();render();break;case 'draft-replace':{const pending=pendingTransaction;drafts().clear();pendingTransaction=null;if(pending)showTransaction(pending.id,pending.kind,pending.prefill);else showTransaction();break;}
 case 'tx-more':txVisible+=50;document.querySelector('#tx-table').innerHTML=transactionTable();break;
 case 'clear-tx-filters':search='';filterType='';filterAccount='';filterCategory='';filterSubcategory='';filterPati='';filterDate='';allTransactions=false;txVisible=50;render();break;
 case 'demo':demo=!demo;state=demo?(demoState||(demoState=makeDemo())):realState;render();break;
 case 'backup':backup();break;case 'restore':document.querySelector('#restore-file').click();break;
 case 'raw-backup':download(localStorage.getItem(KEY)||'{}','spokojnie-surowa-kopia.json','application/json');break;
 case 'exportcsv':exportCSV();break;case 'export-all':exportCSV(true);break;
 case 'copy-budget':{const prev=new Date(month+'-15T12:00:00');prev.setMonth(prev.getMonth()-1);const key=`${prev.getFullYear()}-${String(prev.getMonth()+1).padStart(2,'0')}`;const b=budgetFor(state,key);commit(s=>{s.budgets[month]={...b};},'Skopiowano wcześniejszy plan');break;}
 case 'import':showImport();break;
 default:if(!investments.action(el.dataset.action,el))features.action(el.dataset.action,el);break;
 }
}
document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='n'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!modal.open){e.preventDefault();showTransaction();}});
function showImport(){
 openModal('Import historii z CSV',`<p class="sub">Plik odczytamy w tej przeglądarce. Najpierw wybierzesz kolumny, potem sprawdzisz wszystkie wiersze.</p><form id="import-file-form" style="margin-top:20px"><label class="field"><span>Konto, którego historię importujesz</span><select name="account">${accountOptions('bnp')}</select></label><div class="formgrid"><label class="field"><span>Kodowanie znaków</span><select name="encoding"><option value="utf-8">UTF-8</option><option value="windows-1250">Windows-1250</option></select></label><label class="field"><span>Separator kolumn</span><select name="delimiter"><option value="">Wykryj automatycznie</option><option value=";">Średnik ;</option><option value=",">Przecinek ,</option><option value="tab">Tabulator</option></select></label></div><label class="field"><span>Plik CSV z nagłówkami (maks. 5 MB)</span><input name="file" type="file" accept=".csv,.txt,text/csv" required></label><p class="notice">Import nie jest automatycznym połączeniem z bankiem. Wybierz plik historii złotówkowego konta. Wiersze sprzed salda początkowego będą niedostępne.</p><div class="error" id="import-error" role="alert"></div><div class="form-actions"><button class="button primary" type="submit">Dalej: wybierz kolumny</button></div></form>`);
 modal.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target),file=fd.get('file');if(file.size>5000000){modal.querySelector('#import-error').textContent='Plik ma więcej niż 5 MB. Podziel historię na mniejsze pliki.';return;}try{const text=new TextDecoder(fd.get('encoding')).decode(await file.arrayBuffer()),parsed=parseCSV(text,fd.get('delimiter')==='tab'?'\t':fd.get('delimiter')||undefined);modal.close();showMapping(parsed,fd.get('account'));}catch(err){modal.querySelector('#import-error').textContent=err.message;}});
}
function showMapping(parsed,account){
 const options=(name,regex)=>`<select name="${name}">${parsed.headers.map((h,i)=>`<option value="${i}" ${regex.test(h)?'selected':''}>${esc(h||'Kolumna '+(i+1))}</option>`).join('')}</select>`;
 openModal('Dopasuj kolumny',`<form id="mapping-form"><div class="steps"><span>1. Plik ✓</span>→<span>2. Kolumny</span>→<span>3. Podgląd i zapis</span></div><p class="sub">Konto: ${esc(state.accounts.find(a=>a.id===account)?.name)} · ${parsed.rows.length} wierszy</p><div class="formgrid" style="margin-top:20px"><label class="field"><span>Data</span>${options('date',/^data|date/i)}</label><label class="field"><span>Opis</span>${options('description',/opis|tytuł|tytul|description/i)}</label><label class="field"><span>Kwota</span>${options('amount',/^kwota$|amount/i)}</label><label class="field"><span>Znaczenie kwoty</span><select name="mode"><option value="signed">Minus = wydatek, plus = wpływ</option><option value="expense">Wszystkie kwoty = wydatki</option><option value="income">Wszystkie kwoty = wpływy</option></select></label></div><p class="smallprint">Obsługujemy jedną kolumnę kwoty, złotówki, daty RRRR-MM-DD i DD.MM.RRRR. Przy osobnych kolumnach uznań/obciążeń przygotuj jedną kolumnę kwoty albo importuj dwa pliki. Waluta inna niż PLN wymaga wcześniejszego przeliczenia.</p><div class="table-wrap" style="margin-top:15px"><table><thead><tr>${parsed.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${parsed.rows.slice(0,3).map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="form-actions"><button class="button primary" type="submit">Pokaż transakcje do sprawdzenia</button></div></form>`,true);
 modal.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.target),seen=new Set(state.transactions.map(fingerprint)),rows=parsed.rows.map((r,i)=>{
 const raw=moneyInput(r[Number(fd.get('amount'))]),type=fd.get('mode')==='signed'?(raw<0?'expense':'income'):fd.get('mode');
 const t={id:uid(),account,date:dateInput(r[Number(fd.get('date'))])||String(r[Number(fd.get('date'))]),description:String(r[Number(fd.get('description'))]||'').trim(),amount:Math.abs(raw),type,category:'once'};
 let error='';try{validateTransaction(t,state);}catch(err){error=err.message;}const fp=fingerprint(t),duplicate=seen.has(fp);seen.add(fp);return {t,error,duplicate,checked:!error&&!duplicate,index:i};
 });modal.close();showImportPreview(rows);});
}
function showImportPreview(rows){
 openModal('Sprawdź, zanim zapiszesz',`<div class="notice">Sprawdź szczególnie wpływy: zwrot zakupu oznacz jako „Zwrot”, a przelewy między własnymi kontami jako „Przelew” i wybierz konto docelowe. Przy imporcie drugiego konta odznacz lustrzaną stronę tego samego przelewu. Aplikacja nie rozpozna jej automatycznie.</div><p class="sub">${rows.length} wierszy · ${rows.filter(r=>r.duplicate).length} podobnych do już wczytanych (odznaczone). Dwa prawdziwe, identyczne zakupy możesz zaznaczyć ręcznie.</p><div class="table-wrap" style="max-height:45vh;margin-top:15px"><table class="import-table"><thead><tr><th>Zapisz</th><th>Data i opis</th><th class="num">Kwota</th><th>Rodzaj</th><th>Kategoria / cel</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${r.error?'invalid':''}" data-importrow="${i}"><td><input type="checkbox" data-rowcheck="${i}" aria-label="Zapisz wiersz ${i+1}" ${r.checked?'checked':''} ${r.error?'disabled':''}></td><td>${esc(r.t.description)}<small>${esc(r.t.date)}${r.duplicate?' · możliwy duplikat':''}</small>${r.error?'<small class="over">'+esc(r.error)+'</small>':''}</td><td class="num">${Number.isFinite(r.t.amount)?money(r.t.amount):'Błędna kwota'}</td><td><select data-rowtype="${i}" aria-label="Rodzaj wiersza ${i+1}" ${r.error?'disabled':''}>${Object.entries(types).map(([k,v])=>`<option value="${k}" ${r.t.type===k?'selected':''}>${v}</option>`).join('')}</select></td><td><select data-rowcat="${i}" aria-label="Kategoria wiersza ${i+1}">${categories.map(c=>`<option value="${c.id}" ${c.id==='once'?'selected':''}>${c.name}</option>`).join('')}</select><select data-rowto="${i}" aria-label="Konto docelowe wiersza ${i+1}" hidden><option value="">Wybierz konto docelowe</option>${accountOptions('')}</select></td></tr>`).join('')}</tbody></table></div><div class="error" id="preview-error" style="margin-top:15px" role="alert"></div><div class="form-actions">${btn('Anuluj','close')}<button id="import-confirm" class="button primary">Zapisz zaznaczone transakcje</button></div>`,true);
 modal.querySelectorAll('[data-rowtype]').forEach(el=>el.addEventListener('change',()=>{const i=Number(el.dataset.rowtype);rows[i].t.type=el.value;modal.querySelector(`[data-rowcat="${i}"]`).hidden=!['expense','refund'].includes(el.value);modal.querySelector(`[data-rowto="${i}"]`).hidden=el.value!=='transfer';}));
 modal.querySelectorAll('[data-rowcat]').forEach(el=>{el.hidden=!['expense','refund'].includes(rows[Number(el.dataset.rowcat)].t.type);});
 modal.querySelector('#import-confirm').addEventListener('click',()=>{const tx=[];for(const r of rows){if(!modal.querySelector(`[data-rowcheck="${r.index}"]`).checked)continue;const t={...r.t,category:modal.querySelector(`[data-rowcat="${r.index}"]`).value};if(t.type==='transfer')t.to=modal.querySelector(`[data-rowto="${r.index}"]`).value;try{validateTransaction(t,state);}catch(err){modal.querySelector('#preview-error').textContent=`Wiersz ${r.index+1}: ${err.message}`;return;}tx.push(t);}if(!tx.length){modal.querySelector('#preview-error').textContent='Zaznacz co najmniej jedną poprawną transakcję.';return;}if(commit(s=>{s.transactions.push(...tx);},`Zaimportowano ${tx.length} transakcji`)){modal.close();page='transactions';render();}});
}
const features=createFeatures({getState:()=>state,getMonth:()=>month,isDemo:()=>demo,esc,money,number,btn,icon,heading,monthInput,openModal,toast,commit,render,showTransaction});
const workspace=createWorkspace({getState:()=>state,getMonth:()=>month,getPage:()=>page,isDemo:()=>demo,setMonth:m=>{if(/^\d{4}-(0[1-9]|1[0-2])$/.test(m)){month=m;render();}},esc,money,number,btn,icon,heading,monthInput,openModal,commit,toast,render,showTransaction,navigate,openTransactions});
const investments=createInvestments({getState:()=>state,getPage:()=>page,isDemo:()=>demo,canSync:()=>cloudPhase==='ready'&&!storageError,openCashCheck:()=>{navigate('checks');},esc,money,btn,icon,heading,openModal,commit,render,toast});
modal.addEventListener('close',()=>{if(modal.open)return;render();const title=document.querySelector('#view h1');if(title){title.tabIndex=-1;title.focus({preventScroll:true});}});
render();
if(!storageError)cloud.bootstrap(realState);else{cloudPhase='offline';cloudMessage=storageError;render();}
window.addEventListener('online',()=>{if(!storageError)cloud.retry(realState);});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue&&e.newValue!==JSON.stringify(realState)){cloud.enabled=false;cloud.status('conflict');}});
